<?php require 'config.php';if(!empty($_SESSION['admin']))redirect('admin/index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT * FROM admins WHERE username=?');$s->execute([trim($_POST['username']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin']=['id'=>$a['id'],'username'=>$a['username']];redirect('admin/index.php');}$error='Admin username or password is incorrect.';}$page_title='Admin sign in';require 'partials/header.php';?><section class="panel narrow"><span class="eyebrow">RESTRICTED ACCESS</span><h1>Admin sign in</h1><p class="muted">Administrator access is separate from customer login.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Username</label><input name="username" required autocomplete="username"></div><div class="field"><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div><button class="btn btn-primary full">Enter admin area →</button></form></section><?php require 'partials/footer.php';?>
